// A donut chart: parts of a whole. The markup is an ordered list — one item per slice, its name and its share as text — so
// with the stylesheet off it reads as a list of shares. The ring is the items' own `::before`: a full circle painted by a
// `conic-gradient()` only between the item's two angles, masked to a ring and clipped to its own wedge, and the legend row is
// the item itself, so hovering a slice and hovering its row are the same gesture.
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { For } from "solid-js";

import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** What `render` gets: the props of the list, `data-part` and the caller's class merged in. */
export type DonutPartProps = PartProps;

/** One slice: its name and its amount. The shares are the component's, not the caller's. */
export interface DonutSlice {
  readonly label: string;
  readonly value: number;
}

export interface DonutProps extends Renderable<DonutPartProps, void> {
  /** The slices, clockwise from twelve o'clock. */
  readonly slices: ReadonlyArray<DonutSlice>;
  /** The chart's name, which also names the list: "Traffic by region". */
  readonly label: string;
  /** A slice as a reader sees it; the second number is its share of the whole, in percent. */
  readonly format?: (value: number, share: number) => string;
  /** The ring's diameter, a CSS length; it shrinks with a narrow page. @default "11rem" */
  readonly size?: string;
  readonly class?: string;
}

// The theme's own colours, in the order the slices take them: the accent first, then the neutral ramp around it. A slice's
// colour is its index, so two charts of the same data paint the same slices. Colour is never the only channel: each row names
// its slice and its share. The fallbacks are the theme's light values: a page without the registered tint tokens (a bare
// stylesheet, a test page) still paints the ring.
const SLICE_COLORS: ReadonlyArray<string> = [
  "var(--color-highlight, #717171)",
  "var(--color-gray-700)",
  "var(--color-gray-1000)",
  "var(--color-gray-1300)",
  "var(--color-gray-500)",
  "var(--color-link, #4a4a4a)",
];

// The points of a wedge, a quarter of the arc apart: the centre and five steps on the circle. Placed with `sin()`/`cos()` on
// the item's own angles, so one rule draws every slice. The 71% radius reaches the corners of the box, so the polygon covers
// the arc at every step of 90° or less.
const arcPoint = (step: number): string =>
  `calc(50% + 71% * sin(var(--f) + var(--s) * ${step})) calc(50% - 71% * cos(var(--f) + var(--s) * ${step}))`;
const wedge = `polygon(50% 50%, ${[0, 1, 2, 3, 4].map(arcPoint).join(", ")})`;

// The list is the legend, and the ring is drawn in the room its inline start padding keeps. `--donut` is the ring's diameter,
// capped by the viewport so a narrow page scales the ring down instead of clipping the legend. A narrow page stacks instead:
// the ring above, the legend at full width below, so a long name keeps its words.
const list = css.cn(
  css.position("relative"),
  css.display("grid"),
  css.alignContent("center"),
  css.gap(t.space._1),
  css.minHeight("var(--donut)"),
  css.margin(0),
  css.padding(0),
  css.paddingInlineStart("calc(var(--donut) + 2rem)"),
  css.listStyle("square inside"),
  css.fontSize(t.font.size),
  css.color(t.color.text),
  css.overflowWrap("anywhere"),
  css.media("(max-width: 30rem)")(
    css.paddingInlineStart("0"),
    css.paddingBlockStart("calc(var(--donut) + 2rem)"),
  ),
);

// One slice: a marker in the slice's colour, its name, and its share pushed to the end of the row. The slice itself is the
// `::before` — positioned against the list, not the row — so the rows stay a legend and the ring stays one circle. The clip
// shapes the hit area too: without it the transparent rest of each circle would catch the pointer and the last one would win
// every hover.
const item = css.cn(
  css.markerElement(css.color("var(--c)")),
  css.cursor("default"),
  css.paddingBlock("2px"),
  css.hover(css.before(css.scale("1.05"))),
  css.before(
    css.content('""'),
    css.position("absolute"),
    css.left("0"),
    css.top("calc(50% - var(--donut) / 2)"),
    css.width("var(--donut)"),
    css.aspectRatio("1"),
    css.borderRadius("50%"),
    css.background(
      "conic-gradient(var(--c) calc(var(--f) + .6deg) calc(var(--t) - .6deg), transparent 0)",
    ),
    css.mask("radial-gradient(closest-side, transparent 58%, #000 calc(58% + 1px))"),
    css.clipPath(wedge),
    // stacked, the ring sits above the legend, centred in the list's own width
    css.media("(max-width: 30rem)")(
      css.top("0"),
      css.left("50%"),
      css.marginLeft("calc(var(--donut) / -2)"),
    ),
    css.media("(prefers-reduced-motion: no-preference)")(css.transition("scale 150ms")),
  ),
);

// The name takes the row's start; the share floats to its end, so a long name wraps under itself instead of under the number.
const name = css.cn(css.fontWeight("500"));
const share = css.cn(
  css.float("right"),
  css.paddingInlineStart(t.space._2),
  css.color(t.color.muted),
);

// The figure is the whole chart: the caption names it, and the list under it is the data.
const frame = css.cn(css.display("grid"), css.width("100%"), css.margin(0), css.gap(t.space._1));
const caption = css.cn(css.fontSize(t.font.sizeSm), css.color(t.color.muted));

const weight = (slice: DonutSlice): number =>
  Number.isFinite(slice.value) && slice.value > 0 ? slice.value : 0;

// what a row's `<data value>` says: the same number its text shows, as the article's own markup does
const shown = (shareOf: number): number => Math.round(shareOf * 10) / 10;
const percent = (shareOf: number): string => `${shown(shareOf)}%`;

/**
 * A donut chart: parts of a whole, as a ring beside the shares it is made of.
 *
 * The caller gives the amounts; the component adds them up and states each slice's start and end in percent, because CSS
 * cannot add up earlier siblings. The ring is decoration painted by the rows' pseudo-elements, and every value is text in its
 * row, so a reader without a pointer — or without the stylesheet — still gets the whole chart.
 */
export const Donut = (props: DonutProps): JSX.Element => {
  const total = (): number => props.slices.reduce((sum, slice) => sum + weight(slice), 0);
  const shareOf = (slice: DonutSlice): number => {
    const sum = total();
    return sum === 0 ? 0 : (weight(slice) / sum) * 100;
  };
  // The bands tile the circle: each starts where the one before it ended, and the last ends on 100. A chart of zeroes paints
  // nothing instead of a full ring.
  const bands = (): ReadonlyArray<{ from: number; to: number }> => {
    const sum = total();
    let reached = 0;
    return props.slices.map((slice, index) => {
      const from = sum === 0 ? 0 : (reached / sum) * 100;
      reached += weight(slice);
      const last = index === props.slices.length - 1;
      return { from, to: sum === 0 ? 0 : last ? 100 : (reached / sum) * 100 };
    });
  };
  const show = (slice: DonutSlice): string =>
    (props.format ?? ((_, shareOfSlice: number) => percent(shareOfSlice)))(
      weight(slice),
      shareOf(slice),
    );
  const size = (): string => props.size ?? "11rem";

  const own = {
    "data-part": "donut",
    get class() {
      return css.cn(list, props.class);
    },
    get style() {
      return {
        "--donut-size": size(),
        "--donut": "min(var(--donut-size), 45vw)",
      } as never;
    },
  } as unknown as PartProps;

  return (
    <figure data-part="donut-frame" class={frame}>
      <figcaption data-part="donut-caption" class={caption}>
        {props.label}
      </figcaption>
      {renderPart(props, own, undefined, (part) => (
        <ol {...part}>
          <For each={props.slices}>
            {(slice, index) => {
              const band = (): { from: number; to: number } =>
                bands()[index()] ?? { from: 0, to: 0 };
              return (
                <li
                  data-part="donut-slice"
                  class={item}
                  style={
                    {
                      "--from": band().from,
                      "--to": band().to,
                      // the angles the ring and its clip are drawn from, as the article computes them
                      "--f": "calc(var(--from) * 3.6deg)",
                      "--t": "calc(var(--to) * 3.6deg)",
                      "--s": "calc((var(--t) - var(--f)) / 4)",
                      "--c": SLICE_COLORS[index() % SLICE_COLORS.length],
                    } as never
                  }
                >
                  <span data-part="donut-label" class={name}>
                    {slice.label}
                  </span>{" "}
                  <data data-part="donut-share" class={share} value={String(shown(shareOf(slice)))}>
                    {show(slice)}
                  </data>
                </li>
              );
            }}
          </For>
        </ol>
      ))}
    </figure>
  );
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

// The donut's conformance, to the charts epic's accessibility checklist: the list is the data and reads as "name, share", the
// ring is the items' decoration, every share is text, the caption names the figure, and a hover lifts the ring without moving
// the page. The tests read the DOM and the computed pseudo-elements; only the hover one needs a pointer.
import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import { describe, expect, it } from "vite-plus/test";
import { userEvent } from "vite-plus/test/browser";

import { Donut, type DonutSlice } from "./donut.tsx";

const mount = (element: () => JSX.Element) => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(element, root);
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

const SLICES: ReadonlyArray<DonutSlice> = [
  { label: "Europe", value: 38 },
  { label: "North America", value: 31 },
  { label: "Asia", value: 18 },
  { label: "South America", value: 8 },
  { label: "Oceania", value: 5 },
];

const slices = (root: HTMLElement): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="donut-slice"]'),
];
const band = (slice: HTMLElement): { from: number; to: number } => ({
  from: Number.parseFloat(slice.style.getPropertyValue("--from")),
  to: Number.parseFloat(slice.style.getPropertyValue("--to")),
});
const ring = (slice: HTMLElement): CSSStyleDeclaration => getComputedStyle(slice, "::before");

describe("Donut", () => {
  it("is a named figure over one item per slice, its name and its share in text", () => {
    const { root, dispose } = mount(() => <Donut label="Traffic by region" slices={SLICES} />);
    expect(root.querySelector("figcaption")?.textContent).toBe("Traffic by region");
    const rows = slices(root);
    expect(rows).toHaveLength(5);
    // the reading order is the name and then its share, and the share is the item's own data
    expect(rows.map((row) => row.textContent?.replace(/\s+/g, ""))).toEqual([
      "Europe38%",
      "NorthAmerica31%",
      "Asia18%",
      "SouthAmerica8%",
      "Oceania5%",
    ]);
    expect(rows[1]?.querySelector("data")?.getAttribute("value")).toBe("31");
    // no value is hover-only: every share is in the document before any pointer
    expect(rows.every((row) => (row.querySelector("data")?.textContent ?? "").endsWith("%"))).toBe(
      true,
    );
    dispose();
  });

  it("tiles the circle with the slices' bands, in the order they are read", () => {
    const { root, dispose } = mount(() => <Donut label="Traffic by region" slices={SLICES} />);
    const bands = slices(root).map(band);
    expect(bands[0]?.from).toBe(0);
    expect(bands.at(-1)?.to).toBe(100);
    for (let index = 1; index < bands.length; index += 1) {
      // each band starts where the one before it ends: no gap, no overlap
      expect(bands[index]?.from).toBeCloseTo(bands[index - 1]!.to, 6);
      // and its width is the slice's share of the whole (the values sum to 100)
      expect(bands[index]!.to - bands[index]!.from).toBeCloseTo(SLICES[index]!.value, 6);
    }
    dispose();
  });

  it("paints the slice as the item's ring: a conic gradient, masked to a ring and clipped to its wedge", () => {
    const { root, dispose } = mount(() => <Donut label="Traffic by region" slices={SLICES} />);
    const slice = slices(root)[0]!;
    const painted = ring(slice);
    // a pseudo-element paints nothing without content
    expect(painted.content).toBe('""');
    expect(painted.backgroundImage).toContain("conic-gradient");
    // the hole and the hit area: a radial mask makes the ring, the polygon lets only the wedge take a hover
    expect(painted.maskImage).toContain("radial-gradient");
    expect(painted.clipPath).toContain("polygon");
    expect(painted.width).toBe(painted.height);
    // the slice's colour is its index, drawn from the theme's own tokens
    expect(slice.style.getPropertyValue("--c")).toBe("var(--color-highlight, #717171)");
    expect(slices(root)[1]?.style.getPropertyValue("--c")).toBe("var(--color-gray-700)");
    dispose();
  });

  it("takes the page's formatting and size", () => {
    const { root, dispose } = mount(() => (
      <Donut
        label="Sign-ups"
        size="7rem"
        slices={[
          { label: "Free", value: 3 },
          { label: "Paid", value: 1 },
        ]}
        format={(value, shareOf) => `${value} (${shareOf}%)`}
      />
    ));
    const list = root.querySelector<HTMLElement>('[data-part="donut"]')!;
    expect(list.style.getPropertyValue("--donut-size")).toBe("7rem");
    expect(slices(root)[0]?.querySelector("data")?.textContent).toBe("3 (75%)");
    // the data is the share, as the row shows it, whatever the page's formatting
    expect(slices(root)[0]?.querySelector("data")?.getAttribute("value")).toBe("75");
    dispose();
  });

  it("paints nothing for a chart of zeroes instead of a full ring", () => {
    const { root, dispose } = mount(() => (
      <Donut
        label="Nothing yet"
        slices={[
          { label: "A", value: 0 },
          { label: "B", value: 0 },
        ]}
      />
    ));
    expect(slices(root).map(band)).toEqual([
      { from: 0, to: 0 },
      { from: 0, to: 0 },
    ]);
    expect(slices(root)[0]?.querySelector("data")?.textContent).toBe("0%");
    dispose();
  });

  it("lifts the ring on hover without moving the page", async () => {
    const { root, dispose } = mount(() => <Donut label="Traffic by region" slices={SLICES} />);
    const list = root.querySelector<HTMLElement>('[data-part="donut"]')!;
    const before = {
      list: list.getBoundingClientRect(),
      rows: slices(root).map((row) => row.getBoundingClientRect()),
    };
    await userEvent.hover(slices(root)[0]!);
    // the ring's lift is a transition: let it arrive before reading it
    await new Promise((resolve) => setTimeout(resolve, 250));
    // the hover is a scale on the pseudo-element: the legend keeps every box it had
    const after = {
      list: list.getBoundingClientRect(),
      rows: slices(root).map((row) => row.getBoundingClientRect()),
    };
    expect(after.list.height).toBe(before.list.height);
    expect(after.list.width).toBe(before.list.width);
    expect(after.rows.map((rect) => [rect.width, rect.height])).toEqual(
      before.rows.map((rect) => [rect.width, rect.height]),
    );
    expect(getComputedStyle(slices(root)[0]!, "::before").scale).toBe("1.05");
    dispose();
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
